UC.open_quote = S("“‘«„‚‹「『")
UC.close_quote = S("”’»‹」』")
UC.amb_quote = S("\"'")
UC.open_bracket = S("([{（［｛【〔〈《")
UC.close_bracket = S(")]}）］｝】〕〉》")
UC.dash = S("-‐‑‒–—―−")
UC.hyphen = S("-‐‑")
UC.apostrophe = S("'’ʼ")
UC.currency = S("$€£¥₹¢₩₽₿₪₫₺")
