["nlu/asi/nlu/util.lua"] = [==[
-- asi.nlu.util: deterministic helpers shared by every NLU module.
-- No clock, no global randomness, no I/O except where a function says so.
local U = {}

---------------------------------------------------------------- tables
function U.sorted_keys(t, cmp)
  local ks = {}
  for k in pairs(t) do ks[#ks + 1] = k end
  table.sort(ks, cmp or function(a, b)
    local ta, tb = type(a), type(b)
    if ta ~= tb then return ta < tb end
    return a < b
  end)
  return ks
end

function U.spairs(t, cmp)
  local ks, i = U.sorted_keys(t, cmp), 0
  return function()
    i = i + 1
    local k = ks[i]
    if k ~= nil then return k, t[k] end
  end
end

function U.copy(v, seen)
  if type(v) ~= "table" then return v end
  seen = seen or {}
  if seen[v] then return seen[v] end
  local r = {}
  seen[v] = r
  for k, x in pairs(v) do r[U.copy(k, seen)] = U.copy(x, seen) end
  return setmetatable(r, getmetatable(v))
end

function U.shallow(t)
  local r = {}
  for k, v in pairs(t) do r[k] = v end
  return r
end

function U.append(dst, src)
  for i = 1, #src do dst[#dst + 1] = src[i] end
  return dst
end

function U.set(list)
  local s = {}
  for i = 1, #list do s[list[i]] = true end
  return s
end

function U.count(t)
  local n = 0
  for _ in pairs(t) do n = n + 1 end
  return n
end

function U.clamp(x, lo, hi) if x < lo then return lo elseif x > hi then return hi end return x end
function U.round(x, n) local m = 10 ^ (n or 0); return math.floor(x * m + 0.5) / m end

function U.index_of(list, v)
  for i = 1, #list do if list[i] == v then return i end end
end

function U.map(list, f) local r = {}; for i = 1, #list do r[i] = f(list[i], i) end; return r end
function U.filter(list, f) local r = {}; for i = 1, #list do if f(list[i], i) then r[#r + 1] = list[i] end end; return r end

function U.deep_equal(a, b)
  if a == b then return true end
  if type(a) ~= "table" or type(b) ~= "table" then return false end
  for k, v in pairs(a) do if not U.deep_equal(v, b[k]) then return false end end
  for k in pairs(b) do if a[k] == nil then return false end end
  return true
end

---------------------------------------------------------------- strings
function U.trim(s) return (s:gsub("^%s+", ""):gsub("%s+$", "")) end
function U.startswith(s, p) return s:sub(1, #p) == p end
function U.endswith(s, p) return p == "" or s:sub(-#p) == p end

function U.split(s, sep, plain)
  local out, pos = {}, 1
  if s == "" then return out end
  while true do
    local a, b = s:find(sep, pos, plain ~= false)
    if not a then out[#out + 1] = s:sub(pos); break end
    out[#out + 1] = s:sub(pos, a - 1)
    pos = b + 1
  end
  return out
end

---------------------------------------------------------------- hashing
local K256 = {
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
  0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
  0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
  0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
  0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
}
local M32 = 0xffffffff
local function rrot(x, n) return ((x >> n) | (x << (32 - n))) & M32 end

function U.sha256(msg)
  local len = #msg
  msg = msg .. "\128" .. string.rep("\0", (55 - len) % 64) .. string.pack(">I8", len * 8)
  local H = { 0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19 }
  local w = {}
  for i = 1, #msg, 64 do
    w[1], w[2], w[3], w[4], w[5], w[6], w[7], w[8], w[9], w[10], w[11], w[12], w[13], w[14], w[15], w[16] =
      string.unpack(">I4I4I4I4I4I4I4I4I4I4I4I4I4I4I4I4", msg, i)
    for t = 17, 64 do
      local x, y = w[t - 15], w[t - 2]
      local s0 = rrot(x, 7) ~ rrot(x, 18) ~ (x >> 3)
      local s1 = rrot(y, 17) ~ rrot(y, 19) ~ (y >> 10)
      w[t] = (w[t - 16] + s0 + w[t - 7] + s1) & M32
    end
    local a, b, c, d, e, f, g, h = H[1], H[2], H[3], H[4], H[5], H[6], H[7], H[8]
    for t = 1, 64 do
      local S1 = rrot(e, 6) ~ rrot(e, 11) ~ rrot(e, 25)
      local ch = (e & f) ~ ((~e) & M32 & g)
      local t1 = (h + S1 + ch + K256[t] + w[t]) & M32
      local S0 = rrot(a, 2) ~ rrot(a, 13) ~ rrot(a, 22)
      local maj = (a & b) ~ (a & c) ~ (b & c)
      local t2 = (S0 + maj) & M32
      h, g, f, e, d, c, b, a = g, f, e, (d + t1) & M32, c, b, a, (t1 + t2) & M32
    end
    H[1] = (H[1] + a) & M32; H[2] = (H[2] + b) & M32; H[3] = (H[3] + c) & M32; H[4] = (H[4] + d) & M32
    H[5] = (H[5] + e) & M32; H[6] = (H[6] + f) & M32; H[7] = (H[7] + g) & M32; H[8] = (H[8] + h) & M32
  end
  return string.format("%08x%08x%08x%08x%08x%08x%08x%08x", H[1], H[2], H[3], H[4], H[5], H[6], H[7], H[8])
end

-- FNV-1a 64 (wrapping integer arithmetic): cheap cache/identity keys, NOT cryptographic.
function U.hash64(s)
  local h = -3750763034362895579 -- 0xcbf29ce484222325 as signed
  for i = 1, #s do h = (h ~ s:byte(i)) * 0x100000001b3 end
  return string.format("%016x", h)
end

-- 128-bit non-cryptographic change-detection hash (two independent FNV-style lanes, one pass).  Used for per-record checksums, where the only requirement
-- is that any edit changes the value; integrity claims (manifests, record integrity, dataset digests) use SHA-256.
function U.hash128(s)
  local a, b = -3750763034362895579, 0x6a09e667f3bcc908
  for i = 1, #s do
    local c = s:byte(i)
    a = (a ~ c) * 0x100000001b3
    b = (b ~ (c + 0x9e)) * 0x1000193 + (a >> 29)
  end
  return string.format("%016x%016x", a, b)
end

---------------------------------------------------------------- deterministic PRNG (splitmix64)
local Rng = {}
Rng.__index = Rng
function U.rng(seed)
  return setmetatable({ s = math.tointeger(seed) or 0x1234567 }, Rng)
end
function Rng:u64()
  self.s = self.s + (-7046029254386353131) -- 0x9E3779B97F4A7C15
  local z = self.s
  z = (z ~ (z >> 30)) * (-4658895280553007687) -- 0xBF58476D1CE4E5B9
  z = (z ~ (z >> 27)) * (-7723592293110705685) -- 0x94D049BB133111EB
  return z ~ (z >> 31)
end
function Rng:float() return (self:u64() >> 11) * (1.0 / 9007199254740992.0) end
function Rng:int(lo, hi) return lo + (self:u64() >> 1) % (hi - lo + 1) end
function Rng:pick(list) return list[self:int(1, #list)] end
function Rng:chance(p) return self:float() < p end
function Rng:shuffle(list)
  for i = #list, 2, -1 do
    local j = self:int(1, i)
    list[i], list[j] = list[j], list[i]
  end
  return list
end

---------------------------------------------------------------- byte-level text safety
-- Replace every maximal run of bytes that is not part of a valid UTF-8 sequence by ONE U+FFFD.  Deterministic; valid text comes back unchanged
-- (second result: whether anything was replaced).  The raw bytes stay recoverable through U.hex when a caller needs the lossless form.
function U.scrub_utf8(s)
  if utf8.len(s) then return s, false end
  local out, pos, n = {}, 1, #s
  while pos <= n do
    local ok, bad = utf8.len(s, pos)
    if ok then out[#out + 1] = s:sub(pos); break end
    if bad > pos then out[#out + 1] = s:sub(pos, bad - 1) end
    out[#out + 1] = "\u{FFFD}"
    local j = bad + 1
    while j <= n and not utf8.len(s, j, j) do j = j + 1 end
    pos = j
  end
  return table.concat(out), true
end

function U.hex(s) return (s:gsub(".", function(c) return string.format("%02x", c:byte()) end)) end

-- Deep copy in which every string (and string key) is made valid UTF-8; sharing and metatables are preserved.
function U.scrub_tree(v, seen)
  local tv = type(v)
  if tv == "string" then return (U.scrub_utf8(v)) end
  if tv ~= "table" or v == U.NULL then return v end
  seen = seen or {}
  if seen[v] then return seen[v] end
  local r = {}
  seen[v] = r
  for k, x in pairs(v) do r[type(k) == "string" and (U.scrub_utf8(k)) or k] = U.scrub_tree(x, seen) end
  return setmetatable(r, getmetatable(v))
end

---------------------------------------------------------------- JSON (strict, bounded, data-only)
U.NULL = setmetatable({}, { __tostring = function() return "null" end })
U.OBJ = { __jsontype = "object" } -- marker metatable for empty objects

local esc = { ['"'] = '\\"', ["\\"] = "\\\\", ["\b"] = "\\b", ["\f"] = "\\f", ["\n"] = "\\n", ["\r"] = "\\r", ["\t"] = "\\t" }
local function enc_str(s, strict)
  if strict and not utf8.len(s) then error("json_encode: invalid UTF-8 in string", 0) end
  return '"' .. s:gsub('[%c"\\]', function(c) return esc[c] or string.format("\\u%04x", c:byte()) end) .. '"'
end

local function is_array(t)
  local n = 0
  for k in pairs(t) do
    if math.type(k) ~= "integer" or k < 1 then return false end
    n = n + 1
  end
  if n == 0 then return getmetatable(t) ~= U.OBJ end
  for i = 1, n do if t[i] == nil then return false end end
  return true
end

local function enc(v, out, opts, depth, indent)
  local tv = type(v)
  if v == nil or v == U.NULL then out[#out + 1] = "null"
  elseif tv == "boolean" then out[#out + 1] = v and "true" or "false"
  elseif tv == "number" then
    if v ~= v or v == math.huge or v == -math.huge then
      if opts.nan_null then out[#out + 1] = "null" else error("json_encode: non-finite number", 0) end
    elseif math.type(v) == "integer" then out[#out + 1] = string.format("%d", v)
    elseif v == math.floor(v) and math.abs(v) < 1e15 then out[#out + 1] = string.format("%d", v) -- 1.0 and 1 are the same JSON number (canonical form)
    else out[#out + 1] = string.format("%.17g", v) end
  elseif tv == "string" then out[#out + 1] = enc_str(v, opts.strict_utf8 ~= false)
  elseif tv == "table" then
    if depth > (opts.max_depth or 100) then error("json_encode: depth limit", 0) end
    local nl, ind2 = "", ""
    if opts.pretty then nl = "\n"; ind2 = indent .. "  " end
    if is_array(v) then
      if #v == 0 then out[#out + 1] = "[]"; return end
      out[#out + 1] = "[" .. nl
      for i = 1, #v do
        out[#out + 1] = ind2
        enc(v[i], out, opts, depth + 1, ind2)
        if i < #v then out[#out + 1] = "," .. nl end
      end
      out[#out + 1] = nl .. indent .. "]"
    else
      local ks = U.sorted_keys(v, function(a, b) return tostring(a) < tostring(b) end)
      local first = true
      out[#out + 1] = "{" .. nl
      for _, k in ipairs(ks) do
        if v[k] ~= nil and type(v[k]) ~= "function" then
          if not first then out[#out + 1] = "," .. nl end
          first = false
          out[#out + 1] = ind2 .. enc_str(tostring(k), false) .. (opts.pretty and ": " or ":")
          enc(v[k], out, opts, depth + 1, ind2)
        end
      end
      if first then out[#out] = "{}" else out[#out + 1] = nl .. indent .. "}" end
    end
  else error("json_encode: unsupported type " .. tv, 0) end
end

-- Canonical (sorted-key) encoder. Errors on NaN/Inf and invalid UTF-8 unless told otherwise.
function U.json_encode(v, opts)
  local out = {}
  enc(v, out, opts or {}, 0, "")
  return table.concat(out)
end

local function jerr(s, i, msg) error({ json = true, pos = i, msg = msg }, 0) end

function U.json_decode(s, opts)
  opts = opts or {}
  local max_depth, max_len = opts.max_depth or 64, opts.max_bytes or 256 * 1024 * 1024
  if #s > max_len then return nil, "json: input too large" end
  if opts.require_utf8 ~= false and not utf8.len(s) then return nil, "json: invalid UTF-8" end
  local pos = 1
  local byte, find, sub = string.byte, string.find, string.sub

  local function ws() pos = find(s, "[^ \t\r\n]", pos) or (#s + 1) end

  local parse_value
  local function parse_string()
    local out, i = {}, pos + 1
    while true do
      local j = find(s, '["\\%c]', i)
      if not j then jerr(s, i, "unterminated string") end
      if j > i then out[#out + 1] = sub(s, i, j - 1) end
      local c = byte(s, j)
      if c == 34 then pos = j + 1; return table.concat(out) end
      if c ~= 92 then jerr(s, j, "control character in string") end
      local e = sub(s, j + 1, j + 1)
      local map = { ['"'] = '"', ["\\"] = "\\", ["/"] = "/", b = "\b", f = "\f", n = "\n", r = "\r", t = "\t" }
      if map[e] then out[#out + 1] = map[e]; i = j + 2
      elseif e == "u" then
        local hex = sub(s, j + 2, j + 5)
        if not hex:match("^%x%x%x%x$") then jerr(s, j, "bad \\u escape") end
        local cp = tonumber(hex, 16)
        i = j + 6
        if cp >= 0xD800 and cp <= 0xDBFF then
          local lo = sub(s, i, i + 5)
          if not lo:match("^\\u[dD][c-fC-F]%x%x$") then jerr(s, j, "lone high surrogate") end
          cp = 0x10000 + ((cp - 0xD800) << 10) + (tonumber(sub(lo, 3), 16) - 0xDC00)
          i = i + 6
        elseif cp >= 0xDC00 and cp <= 0xDFFF then jerr(s, j, "lone low surrogate") end
        out[#out + 1] = utf8.char(cp)
      else jerr(s, j, "bad escape") end
    end
  end

  local function parse_number()
    local a, b = find(s, "^-?%d+%.?%d*[eE]?[+-]?%d*", pos)
    local txt = a and sub(s, a, b)
    if not txt or not txt:match("^-?%d+$") and not txt:match("^-?%d+%.%d+$") and not txt:match("^-?%d+%.?%d*[eE][+-]?%d+$") then
      jerr(s, pos, "bad number")
    end
    if txt:match("^-?0%d") then jerr(s, pos, "leading zero") end
    pos = b + 1
    return math.tointeger(tonumber(txt)) or tonumber(txt)
  end

  function parse_value(depth)
    if depth > max_depth then jerr(s, pos, "depth limit") end
    ws()
    local c = byte(s, pos)
    if c == 123 then -- {
      pos = pos + 1
      local obj = setmetatable({}, U.OBJ)
      ws()
      if byte(s, pos) == 125 then pos = pos + 1; return obj end
      while true do
        ws()
        if byte(s, pos) ~= 34 then jerr(s, pos, "object key expected") end
        local k = parse_string()
        ws()
        if byte(s, pos) ~= 58 then jerr(s, pos, "':' expected") end
        pos = pos + 1
        local v = parse_value(depth + 1)
        if rawget(obj, k) ~= nil and opts.dup_keys ~= "last" then jerr(s, pos, "duplicate key " .. k) end
        if v ~= U.NULL then obj[k] = v end
        ws()
        local d = byte(s, pos)
        pos = pos + 1
        if d == 125 then return obj end
        if d ~= 44 then jerr(s, pos - 1, "',' or '}' expected") end
      end
    elseif c == 91 then -- [
      pos = pos + 1
      local arr = {}
      ws()
      if byte(s, pos) == 93 then pos = pos + 1; return arr end
      while true do
        arr[#arr + 1] = parse_value(depth + 1)
        ws()
        local d = byte(s, pos)
        pos = pos + 1
        if d == 93 then return arr end
        if d ~= 44 then jerr(s, pos - 1, "',' or ']' expected") end
      end
    elseif c == 34 then return parse_string()
    elseif c == 116 and sub(s, pos, pos + 3) == "true" then pos = pos + 4; return true
    elseif c == 102 and sub(s, pos, pos + 4) == "false" then pos = pos + 5; return false
    elseif c == 110 and sub(s, pos, pos + 3) == "null" then pos = pos + 4; return U.NULL
    elseif c and (c == 45 or (c >= 48 and c <= 57)) then return parse_number()
    end
    jerr(s, pos, "unexpected character")
  end

  local ok, res = pcall(function()
    local v = parse_value(0)
    ws()
    if pos <= #s then jerr(s, pos, "trailing data") end
    return v
  end)
  if ok then return res end
  if type(res) == "table" and res.json then return nil, string.format("json: %s at byte %d", res.msg, res.pos) end
  return nil, "json: " .. tostring(res)
end

---------------------------------------------------------------- work meter (integer, deterministic)
local Meter = {}
Meter.__index = Meter
function U.meter(budget)
  return setmetatable({ budget = budget or math.huge, total = 0, c = {}, over = false }, Meter)
end
-- returns false once the budget is exhausted so hot loops can bail out explicitly
function Meter:tick(name, n)
  n = n or 1
  self.total = self.total + n
  self.c[name] = (self.c[name] or 0) + n
  if self.total > self.budget then self.over = true end
  return not self.over
end
function Meter:snapshot()
  local c = {}
  for k, v in pairs(self.c) do c[k] = v end
  return { total = self.total, by_stage = c, budget = self.budget ~= math.huge and self.budget or nil, exceeded = self.over }
end

---------------------------------------------------------------- statistics
function U.wilson(k, n, z)
  z = z or 1.96
  if n == 0 then return 0, 1 end
  local p = k / n
  local d = 1 + z * z / n
  local c = p + z * z / (2 * n)
  local a = z * math.sqrt(p * (1 - p) / n + z * z / (4 * n * n))
  return math.max(0, (c - a) / d), math.min(1, (c + a) / d)
end

function U.mean(xs) local s = 0; for i = 1, #xs do s = s + xs[i] end; return #xs > 0 and s / #xs or 0 end

function U.percentile(sorted, p)
  if #sorted == 0 then return 0 end
  local idx = U.clamp(math.floor(p * (#sorted - 1) + 0.5) + 1, 1, #sorted)
  return sorted[idx]
end

-- Paired bootstrap of error_reduction = base_err / new_err over per-case 0/1 error vectors.
-- Resamples with new_err == 0 yield +inf (reported as lower bound only).
function U.bootstrap_ratio(base_err, new_err, iters, seed)
  local n, rng = #base_err, U.rng(seed or 7)
  local ratios, inf = {}, 0
  for _ = 1, iters or 1000 do
    local b, w = 0, 0
    for _ = 1, n do
      local i = rng:int(1, n)
      b = b + base_err[i]; w = w + new_err[i]
    end
    if b > 0 then
      if w == 0 then inf = inf + 1; ratios[#ratios + 1] = math.huge else ratios[#ratios + 1] = b / w end
    end
  end
  table.sort(ratios)
  return { lo = U.percentile(ratios, 0.025), hi = U.percentile(ratios, 0.975), n = #ratios, inf = inf }
end

---------------------------------------------------------------- bounded edit distance (OSA / Damerau)
-- a, b: strings (UTF-8) or arrays of codepoints. Returns distance, or maxd + 1 if above maxd.
local function cps(x)
  if type(x) == "table" then return x end
  local r = {}
  for _, c in utf8.codes(x, true) do r[#r + 1] = c end
  return r
end
function U.osa(a, b, maxd)
  a, b = cps(a), cps(b)
  local la, lb = #a, #b
  maxd = maxd or math.max(la, lb)
  if math.abs(la - lb) > maxd then return maxd + 1 end
  local prev2, prev, cur = {}, {}, {}
  for j = 0, lb do prev[j] = j end
  for i = 1, la do
    cur[0] = i
    local rowmin = i
    for j = 1, lb do
      local cost = (a[i] == b[j]) and 0 or 1
      local v = math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + cost)
      if i > 1 and j > 1 and a[i] == b[j - 1] and a[i - 1] == b[j] then v = math.min(v, prev2[j - 2] + 1) end
      cur[j] = v
      if v < rowmin then rowmin = v end
    end
    if rowmin > maxd then return maxd + 1 end
    prev2, prev, cur = prev, cur, prev2
  end
  local d = prev[lb]
  return d > maxd and maxd + 1 or d
end

---------------------------------------------------------------- tiny schema validator
-- spec: {type="string"|"number"|"integer"|"boolean"|"table"|"array"|"object"|"enum"|"any",
--        required=bool, min=, max=, of=spec (array), fields={name=spec}, extra=bool, values={...} (enum)}
function U.validate(spec, v, path, errs)
  path, errs = path or "$", errs or {}
  local function bad(msg) errs[#errs + 1] = path .. ": " .. msg end
  if v == nil then
    if spec.required then bad("required field missing") end
    return #errs == 0, errs
  end
  local t = spec.type or "any"
  if t == "any" then return #errs == 0, errs end
  if t == "string" then
    if type(v) ~= "string" then bad("expected string") else
      if spec.max and #v > spec.max then bad("string too long") end
      if spec.min and #v < spec.min then bad("string too short") end
    end
  elseif t == "number" or t == "integer" then
    if type(v) ~= "number" or v ~= v or v == math.huge or v == -math.huge then bad("expected finite number")
    else
      if t == "integer" and math.type(v) ~= "integer" and v ~= math.floor(v) then bad("expected integer") end
      if spec.min and v < spec.min then bad("below minimum " .. spec.min) end
      if spec.max and v > spec.max then bad("above maximum " .. spec.max) end
    end
  elseif t == "boolean" then
    if type(v) ~= "boolean" then bad("expected boolean") end
  elseif t == "enum" then
    local ok = false
    for _, x in ipairs(spec.values) do if x == v then ok = true break end end
    if not ok then bad("not in enum {" .. table.concat(spec.values, ",") .. "}") end
  elseif t == "table" then
    if type(v) ~= "table" then bad("expected table") end
  elseif t == "array" then
    if type(v) ~= "table" then bad("expected array")
    else
      if spec.max and #v > spec.max then bad("array too long (" .. #v .. ")") end
      if spec.of then for i = 1, #v do U.validate(spec.of, v[i], path .. "[" .. i .. "]", errs) end end
    end
  elseif t == "object" then
    if type(v) ~= "table" then bad("expected object")
    else
      for name, fs in pairs(spec.fields or {}) do U.validate(fs, v[name], path .. "." .. name, errs) end
      if spec.extra == false then
        for k in pairs(v) do if not (spec.fields or {})[k] then bad("unexpected field " .. tostring(k)) end end
      end
    end
  end
  return #errs == 0, errs
end

return U
]==],
["nlu/asi/nlu/verify.lua"] = [==[
-- asi.nlu.verify: constraint-aware retrieval + SEMANTIC VERIFICATION + evidence sufficiency.
--   stage 1  candidate generation   typed assertion channel (relation, entity)  +  entity mentions  +  phrase-aware BM25F
--   stage 2  semantic verification  every candidate must satisfy: requested entity (identity), relation (id AND direction), answer type, time,
--                                   source constraint, exclusions, modality.  A record that merely mentions the entity, or shares words with
--                                   the question ("capital punishment" for "capital of France"), is NEVER sufficient evidence.
--   stage 3  aggregation            independent support, conflicts (temporal / reliability resolution is explicit), ambiguity across readings,
--                                   and one of: answerable | contradictory | ambiguous | potentially_answerable | insufficient | unsupported
local U = require("asi.nlu.util")
local TU = require("asi.nlu.textutil")

local V = {}
V.STATUS = { "answerable", "potentially_answerable", "ambiguous", "contradictory", "insufficient", "unsupported", "not_applicable" }

V.W = { conflict_gap = 0.30, hedge_weight = 0.5, undated_weight = 0.7, structured_bonus = 0.1, min_strength = 0.4 }

---------------------------------------------------------------- small helpers
local function year_of_key(k) if not k then return nil end return k // 10000 end

local function key_match(desc, variants)
  if not desc then return false end
  for _, v in ipairs(variants) do
    if desc.key == v then return "exact" end
    for _, c in ipairs(desc.cands or {}) do if c.id == v then return "candidate" end end
  end
  return false
end

local function desc_text(d)
  if not d then return "" end
  if d.literal then return d.literal.text end
  return d.text or d.key or ""
end

local function answer_key(kb, d)
  if not d then return nil end
  if d.literal then return "lit:" .. (d.literal.value and tostring(d.literal.value) or d.literal.text:lower()) end
  if d.key then return kb and kb:canonical(d.key) or d.key end
  return "text:" .. (d.text or ""):lower()
end

-- is the relation a "state" (holds over a period) rather than an "event" (happened once)?
local function is_event(kb, rel_id)
  local rel = kb.lex:get_rel(rel_id)
  return rel ~= nil and (rel.when ~= nil or rel.event == true or rel.open == true)
end

local function quote_of(a)
  local t = a.text or ""
  if #t > 320 then t = t:sub(1, 317) .. "..." end
  return t
end

---------------------------------------------------------------- checks
-- time: returns "ok" | "undated" | "past_only" | "mismatch", reason
local function time_check(kb, plan, a, ref_year)
  local req = plan.time or { mode = "current" }
  local ev = is_event(kb, a.rel)
  local lo = a.valid_from or (a.valid_at and a.valid_at.lo) or (a.as_of and a.as_of.lo)
  local hi = a.valid_to or (a.valid_at and a.valid_at.hi) or (a.as_of and a.as_of.hi)
  local dated = lo ~= nil or hi ~= nil
  if req.mode == "current" then
    if ev then return "ok" end                                  -- events do not "end"
    if a.former or a.ended then return "past_only", "the record says this is no longer the case" end
    if a.valid_to and ref_year and year_of_key(a.valid_to) < ref_year then return "past_only", "valid only until " .. tostring(year_of_key(a.valid_to)) end
    if a.tense == "past" and not a.valid_from and not (a.as_of) then return "past_only", "stated in the past tense with no indication that it still holds" end
    return "ok"   -- a present-tense statement is asserted to hold now (as of the record), dated or not
  elseif req.mode == "past_leaning" then
    if ev or a.former or a.ended or a.valid_to or a.tense == "past" then return "ok" end
    return "undated", "a present-tense fact answers a past-tense question only loosely"
  elseif req.mode == "former" then
    if a.former or a.ended or a.valid_to or a.tense == "past" then return "ok" end
    return "mismatch", "the record states a present fact, but a former/historical one was requested"
  elseif req.mode == "at" then
    if not dated then return (ev and "ok") or "undated" end
    local rlo, rhi = req.lo or -math.huge, req.hi or math.huge
    local alo, ahi = lo or -math.huge, hi or math.huge
    if ahi < rlo or alo > rhi then return "mismatch", "the record's validity period does not include the requested time" end
    return "ok"
  elseif req.mode == "after" then
    if not dated then return "undated" end
    if hi and req.lo and hi < req.lo then return "mismatch", "ends before the requested period" end
    return "ok"
  elseif req.mode == "before" then
    if not dated then return "undated" end
    if lo and req.hi and lo > req.hi then return "mismatch", "begins after the requested period" end
    return "ok"
  end
  return "ok"
end

-- source constraint ("the supplied 2020 dataset"): returns "ok" | "unverified" | "mismatch", reason
local function source_check(kb, plan, rec)
  if not plan.sources or #plan.sources == 0 then return "ok" end
  local label = kb:dataset_label_of(rec)
  local verdict, reason = "ok", nil
  for _, s in ipairs(plan.sources) do
    if s.year then
      local have = rec.dataset_year or (label and label.year)
      if have == nil then verdict, reason = "unverified", "the dataset does not declare which year it belongs to"
      elseif have ~= s.year then return "mismatch", string.format("record belongs to the %s dataset, not the requested %s", tostring(have), tostring(s.year)) end
    elseif s.label then
      local have = label and (label.name or label.id)
      if have and not tostring(have):lower():find(tostring(s.label):lower(), 1, true) then
        -- a label we cannot match textually is not proof of mismatch, but it is not verification either
        verdict, reason = "unverified", "the requested source '" .. tostring(s.label) .. "' could not be matched to this dataset's declared label"
      elseif not have then verdict, reason = "unverified", "the dataset declares no label to compare with '" .. tostring(s.label) .. "'" end
    end
  end
  return verdict, reason
end

local function type_check(kb, d, want)
  if not want then return "ok" end
  local ty = d and (d.type or (d.literal and (d.literal.kind == "number" and "number" or d.literal.kind == "temporal" and "date" or "text")))
  if not ty then return "unknown" end
  local fit = kb.lex:compat(ty, want)
  if fit == -1.0 then return "mismatch", "answer is a " .. ty .. ", a " .. want .. " was requested" end
  if fit < 0.5 then return "weak" end
  return "ok"
end

local function excluded_by(kb, plan, d)
  for _, ex in ipairs(plan.exclusions or {}) do
    local t = ex.target
    if t and d then
      if t.type and d.type and kb.lex:compat(d.type, t.type) >= 0.9 then return ex, "answer is a " .. d.type .. ", which the request excludes" end
      if t.text and d.text and (t.scope == "reference" or t.scope == "entity") and t.text:lower() == (d.text or ""):lower() then return ex, "answer is excluded by the request" end
    end
  end
end

---------------------------------------------------------------- evidence items
local function evidence_item(kb, a, role, checks, extra)
  local rec = kb:record(a.record)
  local ds = rec and kb.datasets[rec.dataset]
  local item = { role = role, record = a.record, dataset = rec and rec.dataset, dataset_version = rec and rec.version, source = rec and rec.source,
    field = a.field, quote = quote_of(a), span = { a.s, a.e }, relation = a.rel, polarity = a.polarity, modality = a.modality, tense = a.tense, pattern = a.pattern,
    from = a.from and { key = a.from.key, text = desc_text(a.from), type = a.from.type }, to = a.to and { key = a.to.key, text = desc_text(a.to), type = a.to.type },
    reliability = rec and rec.reliability, reliability_source = rec and rec.reliability_source, structured = a.structured or nil,
    date = rec and rec.date_text, dataset_label = ds and ds.label, checks = checks }
  if a.valid_from then item.valid_from = a.valid_from end
  if a.valid_to then item.valid_to = a.valid_to end
  if a.event_time then item.event_time = a.event_time.year or a.event_time.text end
  if a.former then item.former = true end
  for k, v in pairs(extra or {}) do item[k] = v end
  return item
end

---------------------------------------------------------------- lookup
-- verifies the assertions that bear on (relation, entity reading); returns per-reading outcome
local function verify_assertions(kb, plan, reading, rel_id, known_role, ask_role, answer_type, ref_year, collect)
  local idx = kb.index
  local variants = kb:variants(reading.key)
  local seen, assertions = {}, {}
  -- evidence for a SPECIALISATION of the requested relation also answers it ("Who created X?" is answered by "P founded X"); the reverse never holds
  local rel_ids = { rel_id }
  if not (plan.skip and plan.skip.specialization) then for _, sid in ipairs(kb.lex:specializations(rel_id)) do rel_ids[#rel_ids + 1] = sid end end
  for _, rid in ipairs(rel_ids) do
    for _, vkey in ipairs(variants) do
      local list = (known_role == "from") and idx:assertions_from(rid, vkey) or idx:assertions_to(rid, vkey)
      for _, a in ipairs(list) do if not seen[a.id] then seen[a.id] = true; assertions[#assertions + 1] = a end end
    end
  end
  local rel = kb.lex:get_rel(rel_id)
  if rel and rel.symmetric then
    for _, vkey in ipairs(variants) do
      local list = (known_role == "from") and idx:assertions_to(rel_id, vkey) or idx:assertions_from(rel_id, vkey)
      for _, a in ipairs(list) do if not seen[a.id] then seen[a.id] = true; assertions[#assertions + 1] = a end end
    end
  end
  local out = { supports = {}, refutes = {}, partial = {}, rejected = {}, n_assertions = #assertions }
  local skip = plan.skip or {}   -- ablation switches: which verification checks are disabled (all enabled in production)
  for _, a in ipairs(assertions) do
    local rec = kb:record(a.record)
    local checks = { relation = true }
    local known_desc = known_role == "from" and a.from or a.to
    local ans_desc = ask_role == "to" and a.to or a.from
    local m = key_match(known_desc, variants)
    checks.entity = m or false
    local fails, flags = {}, {}
    if rec and rec.duplicate_of and not skip.duplicates then fails[#fails + 1] = "duplicate of " .. rec.duplicate_of .. " (does not corroborate)" end
    if a.modality == "hypothetical" and not skip.modality then fails[#fails + 1] = "hypothetical statement, not an assertion of fact" end
    if a.is_class then fails[#fails + 1] = "classification, not the requested relation" end
    if m == "candidate" then flags[#flags + 1] = "subject is ambiguous in the record" end
    if a.open_relation then flags[#flags + 1] = "relation word is not in the lexicon (open relation '" .. tostring(a.rel) .. "')" end
    if a.rel ~= rel_id then checks.relation = "specialization"; flags[#flags + 1] = "evidence relation '" .. tostring(a.rel) .. "' is a specialisation of the requested relation '" .. tostring(rel_id) .. "'" end
    local ty, tywhy = type_check(kb, ans_desc, answer_type)
    if skip.type then ty = "ok" end
    checks.answer_type = ty
    if ty == "mismatch" then fails[#fails + 1] = tywhy elseif ty == "unknown" then flags[#flags + 1] = "answer type not established" end
    local tm, twhy = time_check(kb, plan, a, ref_year)
    if skip.time then tm = "ok" end
    checks.time = tm
    if tm == "mismatch" then fails[#fails + 1] = twhy end
    local sm, swhy = source_check(kb, plan, rec)
    if skip.source then sm = "ok" end
    checks.source = sm
    if sm == "mismatch" then fails[#fails + 1] = swhy end
    local ex, exwhy = excluded_by(kb, plan, ans_desc)
    if skip.exclusion then ex = nil end
    checks.exclusion = ex == nil
    if ex then fails[#fails + 1] = exwhy end
    if #fails > 0 then
      out.rejected[#out.rejected + 1] = evidence_item(kb, a, "rejected", checks, { reasons = fails })
    elseif a.polarity == "negative" and not skip.polarity then
      out.refutes[#out.refutes + 1] = { assertion = a, item = evidence_item(kb, a, "refutes", checks, { flags = flags }), key = answer_key(kb, ans_desc) }
    else
      local weak = {}
      if tm == "past_only" then weak[#weak + 1] = twhy end
      if tm == "undated" then flags[#flags + 1] = "undated" end
      if sm == "unverified" then flags[#flags + 1] = swhy end
      if a.modality == "hedged" then flags[#flags + 1] = "hedged ('reportedly', 'maybe', ...)" end
      if reading.fuzzy then flags[#flags + 1] = "the question's entity name matched this record only through a spelling variant" end
      local entry = { assertion = a, key = answer_key(kb, ans_desc), desc = ans_desc, checks = checks, flags = flags, time = tm, source = sm,
        item = evidence_item(kb, a, "supports", checks, { flags = flags }), rec = rec }
      if reading.fuzzy then
        entry.item.role = "partial"
        entry.item.reasons = { "identity of the entity rests on a spelling correction ('" .. tostring(reading.text) .. "' -> '" .. tostring(reading.key) .. "')" }
        out.partial[#out.partial + 1] = entry
      elseif tm == "past_only" then
        entry.item.role = "historical"
        entry.item.reasons = { twhy }
        out.partial[#out.partial + 1] = entry
      elseif sm == "unverified" or (m == "candidate") then
        out.partial[#out.partial + 1] = entry
      else
        out.supports[#out.supports + 1] = entry
      end
    end
  end
  return out
end

-- group supporting entries by answer; independence = distinct non-duplicate records
local function group_answers(kb, entries, skip_rel)
  local groups, order = {}, {}
  for _, e in ipairs(entries) do
    local g = groups[e.key]
    if not g then
      g = { key = e.key, desc = e.desc, text = desc_text(e.desc), type = e.desc and e.desc.type, entries = {}, records = {}, strength = 0, n_records = 0, latest_from = nil }
      groups[e.key] = g
      order[#order + 1] = e.key
    end
    g.entries[#g.entries + 1] = e
    if not g.records[e.assertion.record] then
      g.records[e.assertion.record] = true
      g.n_records = g.n_records + 1
      local w = skip_rel and 0.5 or (e.rec and e.rec.reliability or 0.5)
      if e.assertion.modality == "hedged" then w = w * V.W.hedge_weight end
      if e.time == "undated" then w = w * V.W.undated_weight end
      if e.assertion.structured then w = math.min(1, w + V.W.structured_bonus) end
      g.strength = 1 - (1 - g.strength) * (1 - w)    -- independent sources combine like noisy-OR
    end
    local vf = e.assertion.valid_from or (e.assertion.valid_at and e.assertion.valid_at.lo)
    if vf and (not g.latest_from or vf > g.latest_from) then g.latest_from = vf end
    if e.time == "ok" and (e.assertion.valid_from or e.assertion.valid_at) then g.dated = true end
  end
  local out = {}
  for _, k in ipairs(order) do out[#out + 1] = groups[k] end
  table.sort(out, function(a, b) if a.strength ~= b.strength then return a.strength > b.strength end return a.key < b.key end)
  return out
end

-- choose among competing answers; returns winner|nil, conflict description|nil
local function resolve_groups(groups, refuted)
  if #groups == 0 then return nil end
  -- drop answers a reliable record explicitly denies
  local live, denied = {}, {}
  for _, g in ipairs(groups) do
    local d = refuted[g.key]
    if d and d.strength >= g.strength - 1e-9 and d.n_records >= g.n_records then denied[#denied + 1] = g else live[#live + 1] = g end
  end
  if #live == 0 then return nil, { kind = "all_answers_denied", denied = U.map(denied, function(g) return g.key end) } end
  if #live == 1 then
    return live[1], (#groups > 1) and { kind = "denied_alternatives", resolution = "alternatives are explicitly denied by other records", others = U.map(denied, function(g) return g.key end) } or nil
  end
  -- temporal resolution: a later-starting answer supersedes an earlier one when both are dated
  local dated = {}
  for _, g in ipairs(live) do if g.latest_from then dated[#dated + 1] = g end end
  if #dated == #live then
    table.sort(dated, function(a, b) return a.latest_from > b.latest_from end)
    if dated[1].latest_from ~= dated[2].latest_from then
      return dated[1], { kind = "superseded", resolution = string.format("'%s' (valid from %s) supersedes '%s' (valid from %s)", dated[1].text, tostring(dated[1].latest_from), dated[2].text, tostring(dated[2].latest_from)),
        others = U.map({ table.unpack(dated, 2) }, function(g) return g.key end) }
    end
  end
  -- reliability / corroboration resolution, explicit and only when the gap is clear
  local a, b = live[1], live[2]
  if a.strength - b.strength >= V.W.conflict_gap and a.n_records >= b.n_records then
    return a, { kind = "resolved_by_reliability", resolution = string.format("'%s' (strength %.2f, %d record(s)) outweighs '%s' (strength %.2f, %d record(s))", a.text, a.strength, a.n_records, b.text, b.strength, b.n_records),
      others = U.map({ table.unpack(live, 2) }, function(g) return g.key end) }
  end
  return nil, { kind = "contradiction", answers = U.map(live, function(g) return g.key end) }
end

local function answers_view(groups)
  return U.map(groups, function(g)
    return { key = g.key, text = g.text, type = g.type, strength = U.round(g.strength, 3), independent_records = g.n_records,
      records = U.sorted_keys(g.records) }
  end)
end

---------------------------------------------------------------- topical candidates (kept apart from evidence)
local function topical(kb, plan, readings, handled_records, limit)
  local idx = kb.index
  local out = {}
  local seen = {}
  local rel = plan.relation and kb.lex:get_rel(plan.relation)
  local rel_terms = {}
  if rel then
    for _, n in ipairs(rel.nouns_to or {}) do for _, t in ipairs(TU.terms(n)) do rel_terms[#rel_terms + 1] = t end end
    for _, n in ipairs(rel.nouns_from or {}) do for _, t in ipairs(TU.terms(n)) do rel_terms[#rel_terms + 1] = t end end
    for _, v in ipairs(rel.verbs or {}) do for _, t in ipairs(TU.terms(v.lemma)) do rel_terms[#rel_terms + 1] = t end end
  end
  local rel_set = U.set(rel_terms)
  for _, r in ipairs(readings) do
    for _, vkey in ipairs(kb:variants(r.key)) do
      for _, d in ipairs(idx:docs_mentioning(vkey)) do
        local doc = idx.docs[d]
        if not seen[doc.id] and not handled_records[doc.id] then
          seen[doc.id] = true
          local rec = doc.rec
          -- does the record at least contain the relation's own words?  (then a reader might extract the fact; we could not)
          local words = TU.terms(rec.text or "")
          local shared = 0
          for _, w in ipairs(words) do if rel_set[w] then shared = shared + 1 end end
          local others = {}
          for _, aid in ipairs(doc.assertions) do
            local a = idx.assertions[aid]
            if a and not a.removed and not a.is_class and a.rel ~= plan.relation then others[#others + 1] = a.rel end
          end
          -- instruction-like sentences are withheld from the quote (they stay in the record as untrusted content, never as text a reader could obey)
          local rd = kb.reader_directed[rec.id]
          local text = rec.text or ""
          if rd then
            local parts = {}
            for _, f in ipairs(rec.text_fields or {}) do
              local ft = rec.field_text[f] or ""
              local cuts = {}
              for _, x in ipairs(rd) do if x.field == f then cuts[#cuts + 1] = x end end
              table.sort(cuts, function(a, b) return a.s > b.s end)
              for _, x in ipairs(cuts) do ft = ft:sub(1, x.s - 1) .. "[sentence withheld: instruction-like content]" .. ft:sub(x.e + 1) end
              parts[#parts + 1] = ft
            end
            text = table.concat(parts, "\n")
          end
          out[#out + 1] = { record = doc.id, entity = r.key, shares_relation_words = shared > 0 or nil, other_relations = #others > 0 and others or nil,
            quote = text:sub(1, 200), reliability = rec.reliability, instruction_like = rd and #rd or nil }
        end
      end
    end
  end
  table.sort(out, function(a, b) return a.record < b.record end)
  if limit and #out > limit then for i = #out, limit + 1, -1 do out[i] = nil end end
  return out
end

---------------------------------------------------------------- the entry points
local function reference_year(kb)
  local y
  for _, did in ipairs(kb.dataset_order) do
    local ds = kb.datasets[did]
    if ds.label and ds.label.year and (not y or ds.label.year > y) then y = ds.label.year end
    for _, id in ipairs(ds.order) do
      local r = ds.records[id]
      if r.year and (not y or r.year > y) and not (ds.label and ds.label.year) then y = r.year end
    end
  end
  return y
end

-- ABLATION ONLY ("retrieval without semantic verification"): entity identity + lexical ranking, no relation / type / time / polarity checks.
-- The top records that mention the entity and share words with the relation are returned as "evidence" without being checked.
local function run_untyped(kb, plan, res)
  local readings = plan.subjects or {}
  local rel = plan.relation and kb.lex:get_rel(plan.relation)
  local terms = {}
  if rel then
    for _, n in ipairs(rel.nouns_to or {}) do for _, t in ipairs(TU.terms(n)) do terms[#terms + 1] = t end end
    for _, v in ipairs(rel.verbs or {}) do for _, t in ipairs(TU.terms(v.lemma)) do terms[#terms + 1] = t end end
  end
  local cand = {}
  for _, r in ipairs(readings) do for _, vkey in ipairs(kb:variants(r.key)) do for _, d in ipairs(kb.index:docs_mentioning(vkey)) do cand[d] = true end end end
  local ranked = {}
  for _, hit in ipairs(kb.index:search({ terms = terms, phrases = {} }, 200)) do if cand[hit.doc] then ranked[#ranked + 1] = hit end end
  for d in pairs(cand) do
    local found = false
    for _, h in ipairs(ranked) do if h.doc == d then found = true end end
    if not found then ranked[#ranked + 1] = { doc = d, score = 0 } end
  end
  for i = 1, math.min(3, #ranked) do
    local doc = kb.index.docs[ranked[i].doc]
    res.selected[#res.selected + 1] = { role = "supports", record = doc.id, quote = (doc.rec.text or ""):sub(1, 200), reliability = doc.rec.reliability, unverified = true }
  end
  res.status = (#res.selected > 0) and "answerable" or "unsupported"
  res.untyped = true
end

-- lookup (single relation), including multi-hop chains
local function run_lookup(kb, plan, res)
  if plan.skip and plan.skip.typed then return run_untyped(kb, plan, res) end
  local ref_year = reference_year(kb)
  local readings = plan.subjects or {}
  res.checks_summary = { readings = #readings }
  if #readings == 0 then
    res.status = "insufficient"
    res.reasons[#res.reasons + 1] = "the entity the question is about could not be identified (" .. tostring(plan.subject_status) .. "); no retrieval is possible"
    res.interpretation_incomplete = true
    return
  end
  local per_reading = {}
  local all_rejected, all_refutes = {}, {}
  local handled = {}
  for _, r in ipairs(readings) do
    local out = verify_assertions(kb, plan, r, plan.relation, plan.known_role, plan.ask, plan.answer_type, ref_year)
    for _, e in ipairs(out.supports) do handled[e.assertion.record] = true end
    for _, e in ipairs(out.partial) do handled[e.assertion.record] = true end
    for _, e in ipairs(out.refutes) do handled[e.assertion.record] = true end
    for _, x in ipairs(out.rejected) do handled[x.record] = true; all_rejected[#all_rejected + 1] = x end
    -- refutations indexed by denied answer
    local refuted = {}
    for _, rf in ipairs(out.refutes) do
      local g = refuted[rf.key]
      if not g then g = { strength = 0, n_records = 0, records = {} }; refuted[rf.key] = g end
      if not g.records[rf.assertion.record] then g.records[rf.assertion.record] = true; g.n_records = g.n_records + 1; g.strength = 1 - (1 - g.strength) * (1 - (rf.assertion.reliability or 0.5)) end
      all_refutes[#all_refutes + 1] = rf.item
    end
    local groups = group_answers(kb, out.supports, plan.skip and plan.skip.reliability)
    local winner, conflict = resolve_groups(groups, refuted)
    per_reading[#per_reading + 1] = { reading = r, out = out, groups = groups, winner = winner, conflict = conflict, partial = out.partial }
  end
  res.rejected = all_rejected
  res.refuting = all_refutes
  -- which readings have verified support?  A winner resting only on low-reliability sources is NOT sufficient: it becomes partial evidence.
  local supported = {}
  for _, pr in ipairs(per_reading) do
    if pr.winner and pr.winner.strength < V.W.min_strength and not (plan.skip and plan.skip.reliability) then
      for _, e in ipairs(pr.winner.entries) do
        e.item.role = "partial"
        e.item.reasons = { string.format("the only support is a low-reliability source (strength %.2f < %.2f)", pr.winner.strength, V.W.min_strength) }
        pr.partial[#pr.partial + 1] = e
      end
      pr.winner = nil
    end
    if pr.winner then supported[#supported + 1] = pr end
  end
  local any_conflict, any_partial, any_assertion, any_doc = false, false, false, false
  for _, pr in ipairs(per_reading) do
    if pr.conflict and pr.conflict.kind == "contradiction" then any_conflict = true end
    if #pr.partial > 0 then any_partial = true end
    if pr.out.n_assertions > 0 then any_assertion = true end
    if #kb.index:docs_mentioning(pr.reading.key) > 0 then any_doc = true end
  end
  if #supported >= 2 and #readings >= 2 then
    res.status = "ambiguous"
    res.reasons[#res.reasons + 1] = "the entity mention has several readings and the dataset supports an answer for more than one"
    res.answers_by_reading = U.map(supported, function(pr) return { reading = pr.reading.key, text = pr.reading.text, p = pr.reading.p, answer = pr.winner.text, answer_key = pr.winner.key } end)
    for _, pr in ipairs(supported) do for _, e in ipairs(pr.winner.entries) do res.selected[#res.selected + 1] = e.item end end
  elseif #supported >= 1 then
    local pr = supported[1]
    if #supported == 1 and #readings >= 2 then res.notes[#res.notes + 1] = "the dataset evidence selects the reading '" .. pr.reading.key .. "' among " .. #readings .. " candidates" end
    res.status = "answerable"
    res.reading = pr.reading
    res.answers = answers_view({ pr.winner })
    local alts = {}
    for _, g in ipairs(pr.groups) do if g.key ~= pr.winner.key then alts[#alts + 1] = g end end
    if #alts > 0 then res.alternative_answers = answers_view(alts) end
    res.answer = { key = pr.winner.key, text = pr.winner.text, type = pr.winner.type }
    for _, e in ipairs(pr.winner.entries) do res.selected[#res.selected + 1] = e.item end
    if pr.conflict then
      res.conflicts[#res.conflicts + 1] = pr.conflict
      -- the losing side stays visible, separately, as legitimate conflicting evidence
      for _, g in ipairs(pr.groups) do
        if g.key ~= pr.winner.key then for _, e in ipairs(g.entries) do e.item.role = "conflicting"; res.conflicting_evidence[#res.conflicting_evidence + 1] = e.item end end
      end
    end
    if any_conflict and pr.conflict == nil then res.notes[#res.notes + 1] = "another reading of the entity has contradicting evidence" end
  else
    -- nothing verified
    local contradiction
    for _, pr in ipairs(per_reading) do if pr.conflict and pr.conflict.kind == "contradiction" then contradiction = pr end end
    if contradiction then
      res.status = "contradictory"
      res.conflicts[#res.conflicts + 1] = contradiction.conflict
      res.answers = answers_view(contradiction.groups)
      for _, g in ipairs(contradiction.groups) do for _, e in ipairs(g.entries) do e.item.role = "conflicting"; res.conflicting_evidence[#res.conflicting_evidence + 1] = e.item end end
      res.reasons[#res.reasons + 1] = "records give different answers and neither time, reliability nor corroboration separates them"
    elseif any_partial then
      res.status = "potentially_answerable"
      local why = {}
      for _, pr in ipairs(per_reading) do
        for _, e in ipairs(pr.partial) do
          res.partial_evidence[#res.partial_evidence + 1] = e.item
          why[#why + 1] = (e.item.reasons and e.item.reasons[1]) or (e.flags and e.flags[1]) or "partially verified"
        end
      end
      res.reasons[#res.reasons + 1] = "evidence exists but is not fully verified: " .. table.concat(U.sorted_keys(U.set(why)), "; ")
    elseif #all_rejected > 0 and any_assertion then
      res.status = "insufficient"
      res.reasons[#res.reasons + 1] = "the relation is asserted only in records that fail the question's constraints (type, time, source or exclusions)"
    elseif any_doc then
      res.status = "insufficient"
      res.reasons[#res.reasons + 1] = "records mention the entity but none establishes the requested relation"
    else
      res.status = "unsupported"
      res.reasons[#res.reasons + 1] = "no record in the dataset mentions the requested entity"
    end
  end
  res.topical = topical(kb, plan, readings, handled, 8)
  res.assertion_count = 0
  for _, pr in ipairs(per_reading) do res.assertion_count = res.assertion_count + pr.out.n_assertions end
end

local function run_chain(kb, plan, res)
  -- each step feeds the next: step i's answers become step i+1's known entities
  local ref_year = reference_year(kb)
  local current = nil
  local steps_out = {}
  for _, st in ipairs(plan.chain) do
    local known = st.known
    if st.var or #known == 0 then known = current or {} end
    local sub = { kind = "lookup", relation = st.relation, known_role = st.known_role, ask = st.ask_role, subjects = known, time = plan.time, sources = plan.sources, exclusions = {},
      subject_status = st.known_status }
    local r = U.copy({ selected = {}, rejected = {}, reasons = {}, notes = {}, conflicts = {}, conflicting_evidence = {}, partial_evidence = {}, refuting = {} })
    run_lookup(kb, sub, r)
    steps_out[#steps_out + 1] = { relation = st.relation, status = r.status, answer = r.answer, known = U.map(known, function(k) return k.key end) }
    for _, e in ipairs(r.selected) do e.step = st.index; res.selected[#res.selected + 1] = e end
    for _, e in ipairs(r.rejected) do e.step = st.index; res.rejected[#res.rejected + 1] = e end
    if r.status ~= "answerable" then
      res.status = r.status
      res.reasons[#res.reasons + 1] = string.format("step %d (%s) is %s: %s", st.index, st.relation, r.status, table.concat(r.reasons, "; "))
      res.steps = steps_out
      return false
    end
    current = { { key = r.answer.key, text = r.answer.text, type = r.answer.type, p = 1.0 } }
  end
  res.steps = steps_out
  return true, current
end

function V.run(kb, plan, opts)
  opts = opts or {}
  if opts.skip then plan = U.shallow(plan); plan.skip = opts.skip end
  local res = { status = "not_applicable", reasons = {}, notes = {}, selected = {}, rejected = {}, conflicts = {}, conflicting_evidence = {}, partial_evidence = {},
    refuting = {}, topical = {}, plan_kind = plan.kind, knowledge_digest = kb:digest() }
  if plan.kind == "lookup" then
    if plan.chain and #plan.chain > 0 then
      local ok, current = run_chain(kb, plan, res)
      if ok then
        local final = { kind = "lookup", relation = plan.relation, known_role = plan.known_role, ask = plan.ask, subjects = current, time = plan.time, sources = plan.sources,
          exclusions = plan.exclusions, answer_type = plan.answer_type }
        local r2 = { selected = {}, rejected = {}, reasons = {}, notes = {}, conflicts = {}, conflicting_evidence = {}, partial_evidence = {}, refuting = {}, topical = {} }
        run_lookup(kb, final, r2)
        for k, v in pairs(r2) do
          if type(v) == "table" and #v > 0 and res[k] then for _, x in ipairs(v) do res[k][#res[k] + 1] = x end elseif res[k] == nil or type(v) ~= "table" then res[k] = v end
        end
        res.status, res.answer, res.answers, res.reading = r2.status, r2.answer, r2.answers, r2.reading
      end
    else
      run_lookup(kb, plan, res)
    end
  elseif plan.kind == "verify" then
    -- "Is Paris the capital of France?" -> look up the relation for the known side and compare with the stated other side
    local from_r, to_r = plan.from_readings or {}, plan.to_readings or {}
    if #from_r == 0 or #to_r == 0 or not plan.relation then
      res.status = "insufficient"
      res.reasons[#res.reasons + 1] = "the claim to verify is not fully identified"
      res.interpretation_incomplete = true
    else
      local sub = { kind = "lookup", relation = plan.relation, known_role = "from", ask = "to", subjects = from_r, time = plan.time, sources = plan.sources, exclusions = {} }
      run_lookup(kb, sub, res)
      res.claim = { from = from_r[1].key, to = to_r[1].key }
      if res.status == "answerable" then
        local match = false
        for _, rd in ipairs(to_r) do if kb:canonical(rd.key) == res.answer.key then match = true end end
        res.verdict = match and "supported" or "contradicted"
        if not match then res.reasons[#res.reasons + 1] = "the dataset states a different value: " .. tostring(res.answer.text) end
      elseif res.status == "contradictory" then res.verdict = "contested" end
    end
  elseif plan.kind == "define" then
    V.define(kb, plan, res)
  elseif plan.kind == "search" then
    V.search(kb, plan, res)
  elseif plan.kind == "compare" then
    V.compare(kb, plan, res)
  else
    res.status = "not_applicable"
    res.reasons[#res.reasons + 1] = plan.reason or "no retrieval is required for this request"
  end
  res.summary = V.summarise(res)
  return res
end

---------------------------------------------------------------- definitions / descriptions
function V.define(kb, plan, res)
  local idx = kb.index
  local readings = plan.subjects or {}
  if #readings == 0 then res.status = "insufficient"; res.reasons[#res.reasons + 1] = "the term could not be identified"; return end
  local found = {}
  local handled = {}
  for _, r in ipairs(readings) do
    for _, vkey in ipairs(kb:variants(r.key)) do
      for _, a in ipairs(idx:classifications(vkey)) do
        local rec = kb:record(a.record)
        if rec and not rec.duplicate_of and a.polarity ~= "negative" then
          handled[a.record] = true
          found[#found + 1] = { reading = r, item = (function() local it = evidence_item(kb, a, "supports", { relation = "definition", entity = "exact" }); it.class = a.class_text; return it end)(), class_type = a.class_type }
        end
      end
    end
  end
  if #found > 0 then
    -- different class types from different readings = ambiguity retained
    local by_reading = {}
    for _, f in ipairs(found) do by_reading[f.reading.key] = by_reading[f.reading.key] or f end
    local n = 0
    for _ in pairs(by_reading) do n = n + 1 end
    res.status = (n >= 2) and "ambiguous" or "answerable"
    for _, f in ipairs(found) do res.selected[#res.selected + 1] = f.item end
    if n >= 2 then
      res.answers_by_reading = {}
      for k, f in pairs(by_reading) do res.answers_by_reading[#res.answers_by_reading + 1] = { reading = k, text = f.reading.text, answer = f.item.class } end
      table.sort(res.answers_by_reading, function(a, b) return a.reading < b.reading end)
      res.reasons[#res.reasons + 1] = "the term has several readings and the dataset describes more than one"
    else
      res.answer = { text = found[1].item.class, key = "class:" .. tostring(found[1].item.class) }
    end
  else
    local any = false
    for _, r in ipairs(readings) do if #idx:docs_mentioning(r.key) > 0 then any = true end end
    res.status = any and "insufficient" or "unsupported"
    res.reasons[#res.reasons + 1] = any and "records mention the term but none defines it" or "no record mentions the term"
  end
  res.topical = topical(kb, { relation = nil }, readings, handled, 6)
end

---------------------------------------------------------------- set search with positive / negative filters
local function value_matches(kb, a, f)
  -- does assertion `a` (relation of the filter) carry the filter's value?  keys first, then the value's head word (weak, flagged)
  local val = f.value
  if not val then return true, "exact" end
  local to = a.to
  if not to then return false end
  if val.resolved_id and to.key and kb:canonical(to.key) == kb:canonical(val.resolved_id) then return true, "exact" end
  local vt = (val.core or val.text or ""):lower()
  local tt = (to.term or to.text or ""):lower()
  if vt ~= "" and (tt == vt or tt:find(vt, 1, true) or vt:find(tt, 1, true)) then return true, "text" end
  local vs = {}
  for _, t in ipairs(TU.terms(vt)) do vs[t] = true end
  for _, t in ipairs(TU.terms(tt)) do if vs[t] then return true, "term" end end
  return false
end

function V.search(kb, plan, res)
  local idx = kb.index
  local target_type = plan.target and plan.target.type
  local positive, temporal = {}, {}
  for _, f in ipairs(plan.filters or {}) do
    if f.kind == "relation" and (f.polarity or "positive") == "positive" then positive[#positive + 1] = f
    elseif f.kind == "temporal" then temporal[#temporal + 1] = f end
  end
  local negatives = {}
  for _, n in ipairs(plan.exclusions or {}) do negatives[#negatives + 1] = n end
  if #positive + #temporal == 0 then
    res.status = "insufficient"
    res.reasons[#res.reasons + 1] = "the request has no relation or time filter the dataset could be searched on"
    return
  end
  -- candidate entities: everything that is the subject of an assertion bearing on a filter
  local cand = {}
  local function consider(a, role)
    local d = a[role]
    if d and d.key and not d.literal then cand[d.key] = d end
  end
  for _, f in ipairs(positive) do
    local rel = kb.lex:get_rel(f.relation)
    local role = f.target_role == "to" and "from" or "to"
    for _, a in ipairs(idx.assertions) do if not a.removed and a.rel == f.relation and not a.is_class then consider(a, f.target_role == "from" and "to" or "from") end end
  end
  for _, f in ipairs(temporal) do
    for _, a in ipairs(idx.assertions) do
      if not a.removed then
        local rel = kb.lex:get_rel(a.rel)
        if a.rel == f.relation or (rel and rel.when == f.relation) then consider(a, "from") end
      end
    end
  end
  local passed, failed = {}, {}
  local keys = U.sorted_keys(cand)
  for _, key in ipairs(keys) do
    local d = cand[key]
    local ok_all, evidence, why = true, {}, {}
    -- target type
    local ty = d.type
    if target_type and ty and kb.lex:compat(ty, target_type) == -1.0 then ok_all = false; why[#why + 1] = "is a " .. ty .. ", not a " .. target_type end
    if ok_all then
      for _, f in ipairs(positive) do
        local found
        for _, vkey in ipairs(kb:variants(key)) do
          local list = (f.target_role == "from") and idx:assertions_to(f.relation, vkey) or idx:assertions_from(f.relation, vkey)
          for _, a in ipairs(list) do
            local rec = kb:record(a.record)
            if rec and not rec.duplicate_of and a.polarity ~= "negative" and a.modality ~= "hypothetical" then
              local ok = value_matches(kb, a, f)
              if ok then found = found or a end
            end
          end
        end
        if found then evidence[#evidence + 1] = evidence_item(kb, found, "supports", { relation = true, entity = "exact" }) else ok_all = false; why[#why + 1] = "no record states " .. f.relation end
      end
      for _, f in ipairs(temporal) do
        local good
        for _, vkey in ipairs(kb:variants(key)) do
          for _, a in ipairs(idx:assertions_about(vkey)) do
            local rel = kb.lex:get_rel(a.rel)
            local lo, hi
            if a.rel == f.relation and a.to and a.to.literal then lo, hi = a.to.literal.lo, a.to.literal.hi
            elseif rel and rel.when == f.relation and a.event_time then lo, hi = a.event_time.lo, a.event_time.hi end
            if lo then
              local pass
              if f.op == "after" or f.op == "since" then pass = lo >= (f.eff_lo or 0)
              elseif f.op == "before" or f.op == "until" or f.op == "by" then pass = hi and f.eff_hi and hi <= f.eff_hi
              else pass = lo >= (f.eff_lo or -math.huge) and (hi or lo) <= (f.eff_hi or math.huge) end
              if pass then good = good or a end
            end
          end
        end
        if good then evidence[#evidence + 1] = evidence_item(kb, good, "supports", { relation = true, time = "ok" }) else ok_all = false; why[#why + 1] = "no dated record satisfies the time filter" end
      end
    end
    -- exclusions
    if ok_all then
      for _, n in ipairs(negatives) do
        local t = n.target or {}
        if t.type and ty and kb.lex:compat(ty, t.type) >= 0.9 then ok_all = false; why[#why + 1] = "is a " .. ty .. " (excluded)" end
        for _, nf in ipairs(n.filters or {}) do
          if nf.kind == "relation" then
            for _, vkey in ipairs(kb:variants(key)) do
              for _, a in ipairs(idx:assertions_from(nf.relation, vkey)) do
                local rec = kb:record(a.record)
                if rec and not rec.duplicate_of and a.polarity ~= "negative" and value_matches(kb, a, nf) then
                  ok_all = false; why[#why + 1] = "matches the excluded condition (" .. nf.relation .. ")"
                  evidence[#evidence + 1] = evidence_item(kb, a, "excluded_by", { relation = true }, { reasons = { "satisfies the excluded filter" } })
                end
              end
            end
          end
        end
      end
    end
    if ok_all then passed[#passed + 1] = { key = key, text = d.text, type = ty, evidence = evidence }
    else failed[#failed + 1] = { key = key, text = d.text, reasons = why, evidence = evidence } end
  end
  res.matches = passed
  res.excluded_entities = failed
  if #passed > 0 then
    res.status = "answerable"
    for _, m in ipairs(passed) do for _, e in ipairs(m.evidence) do res.selected[#res.selected + 1] = e end end
    res.answers = U.map(passed, function(m) return { key = m.key, text = m.text, type = m.type, independent_records = #m.evidence } end)
  elseif #keys > 0 then
    res.status = "insufficient"
    res.reasons[#res.reasons + 1] = "candidates exist but none satisfies every filter and exclusion"
  else
    res.status = "unsupported"
    res.reasons[#res.reasons + 1] = "the dataset holds no assertions the requested filters could apply to"
  end
end

---------------------------------------------------------------- comparison
function V.compare(kb, plan, res)
  local lex = kb.lex
  local dim = plan.dimension and lex.dims[plan.dimension] or (lex.parent and lex.parent.dims[plan.dimension])
  if not dim or not plan.items or #plan.items < 2 then
    res.status = "insufficient"
    res.reasons[#res.reasons + 1] = "the comparison needs two identified items and a measurable dimension"
    return
  end
  local values, missing = {}, {}
  for _, it in ipairs(plan.items) do
    local got
    for _, r in ipairs(it.readings or {}) do
      for _, rel_id in ipairs(dim.rels or {}) do
        for _, vkey in ipairs(kb:variants(r.key)) do
          for _, a in ipairs(kb.index:assertions_from(rel_id, vkey)) do
            if a.polarity ~= "negative" and a.to and not got then got = { assertion = a, rel = rel_id } end
          end
        end
      end
    end
    if got then
      local v = got.assertion.to.literal and (got.assertion.to.literal.value or got.assertion.to.literal.lo) or nil
      if got.assertion.event_time and not v then v = got.assertion.event_time.lo end
      values[#values + 1] = { item = it.text, value = v, text = desc_text(got.assertion.to), evidence = evidence_item(kb, got.assertion, "supports", { relation = true, entity = "exact" }) }
    else missing[#missing + 1] = it.text end
  end
  for _, v in ipairs(values) do res.selected[#res.selected + 1] = v.evidence end
  res.values = U.map(values, function(v) return { item = v.item, value = v.value, text = v.text } end)
  if #missing == 0 then
    local numeric = true
    for _, v in ipairs(values) do if type(v.value) ~= "number" then numeric = false end end
    res.status = numeric and "answerable" or "potentially_answerable"
    if not numeric then res.reasons[#res.reasons + 1] = "values were found but are not comparable numbers or dates" end
  else
    res.status = (#values > 0) and "potentially_answerable" or "insufficient"
    res.reasons[#res.reasons + 1] = "no value for the dimension was found for: " .. table.concat(missing, ", ")
  end
end

---------------------------------------------------------------- summary line (human + LM readable, derived, never invented)
function V.summarise(res)
  local parts = { "status=" .. res.status }
  if res.answer then parts[#parts + 1] = "answer=" .. tostring(res.answer.text) end
  parts[#parts + 1] = string.format("verified=%d rejected=%d conflicting=%d topical=%d", #res.selected, #res.rejected, #res.conflicting_evidence, #res.topical)
  return table.concat(parts, " ")
end

return V
]==],
["nlu/asi/nlu/vfs.lua"] = [==[
-- asi.nlu.vfs: read-only virtual file layer over the files embedded in the ONE-FILE build (module asi.nlu.embedded).
-- In a source checkout the embedded table does not exist and every function degrades to "nothing is virtual": real files are used.
-- Inside the one-file build the project's own data (gold sets, held-out sets, calibration model, acceptance world, reports, tests, tools) is read from the
-- file itself, so the engine, its evaluation tools and its unit tests run from an empty directory.
--   V.read(path) / V.exists(path) / V.list(prefix)     normalised, project-relative lookups ("./data/eval/dev.cases" == "data/eval/dev.cases")
--   V.install() / V.uninstall()                        wrap io.open / io.lines so unmodified code that opens project paths sees the embedded files
-- Only paths under data/ tests/ tools/ reports/ nlu/ and README.md are virtual; embedded content wins over a real file of the same relative path
-- (the shipped, hash-verified data is what the one-file build evaluates), every other path goes to the real file system untouched.
local V = {}

local ROOTS = { "data/", "tests/", "tools/", "reports/", "nlu/" }

local function embedded()
  local ok, t = pcall(require, "asi.nlu.embedded")
  if ok and type(t) == "table" and type(t.files) == "table" then return t end
  return nil
end

function V.available() return embedded() ~= nil end

-- "./data/eval/dev.cases", "/some/where/data/eval/dev.cases" -> "data/eval/dev.cases" when that file is embedded; nil otherwise
function V.normalize(path)
  local e = embedded()
  if not e or type(path) ~= "string" then return nil end
  local p = path:gsub("^%./+", ""):gsub("//+", "/")
  if e.files[p] then return p end
  -- a path that ends with an embedded project path under an explicit root marker ("<anything>/data/eval/dev.cases")
  for _, root in ipairs(ROOTS) do
    local at = p:find("/" .. root, 1, true)
    if at then
      local rel = p:sub(at + 1)
      if e.files[rel] then return rel end
    end
  end
  return nil
end

function V.read(path)
  local e = embedded()
  if not e then return nil end
  local rel = V.normalize(path)
  return rel and e.files[rel] or nil
end

function V.exists(path) return V.read(path) ~= nil end

function V.list(prefix)
  local e = embedded()
  local out = {}
  if not e then return out end
  for p in pairs(e.files) do if not prefix or p:sub(1, #prefix) == prefix then out[#out + 1] = p end end
  table.sort(out)
  return out
end

---------------------------------------------------------------- an in-memory file object (read-only) with the parts of the io API the project uses
local MemFile = {}
MemFile.__index = MemFile

local function new_memfile(data, name)
  return setmetatable({ data = data, pos = 1, name = name, closed = false }, MemFile)
end

local function read_one(self, fmt)
  local d, p = self.data, self.pos
  if type(fmt) == "number" then
    if fmt == 0 then return (p <= #d) and "" or nil end
    if p > #d then return nil end
    local s = d:sub(p, p + fmt - 1)
    self.pos = p + #s
    return s
  end
  fmt = tostring(fmt or "l"):gsub("^%*", "")
  if fmt == "a" then
    local s = d:sub(p)
    self.pos = #d + 1
    return s
  elseif fmt == "l" or fmt == "L" then
    if p > #d then return nil end
    local nl = d:find("\n", p, true)
    local line
    if nl then
      line = d:sub(p, fmt == "L" and nl or nl - 1)
      self.pos = nl + 1
    else
      line = d:sub(p)
      self.pos = #d + 1
    end
    return line
  elseif fmt == "n" then
    local num = d:match("^%s*([%+%-]?%d+%.?%d*[eE]?[%+%-]?%d*)", p)
    if not num then return nil end
    local _, e2 = d:find("^%s*[%+%-]?%d+%.?%d*[eE]?[%+%-]?%d*", p)
    self.pos = e2 + 1
    return tonumber(num)
  end
  error("bad argument #1 to 'read' (invalid format)", 3)
end

function MemFile:read(...)
  if self.closed then error("attempt to use a closed file", 2) end
  local n = select("#", ...)
  if n == 0 then return read_one(self, "l") end
  local out = {}
  for i = 1, n do
    local v = read_one(self, (select(i, ...)))
    out[i] = v
    if v == nil then break end
  end
  return table.unpack(out, 1, n)
end

function MemFile:lines(...)
  local fmts = table.pack(...)
  return function()
    if fmts.n == 0 then return read_one(self, "l") end
    return self:read(table.unpack(fmts, 1, fmts.n))
  end
end

function MemFile:seek(whence, offset)
  whence = whence or "cur"
  offset = offset or 0
  local base = (whence == "set" and 0) or (whence == "end" and #self.data) or (self.pos - 1)
  local np = base + offset
  if np < 0 then return nil, "invalid seek", 22 end
  self.pos = np + 1
  return np
end

function MemFile:close() self.closed = true; return true end
function MemFile:write() return nil, "virtual file is read-only", 9 end
function MemFile:flush() return self end
function MemFile:setvbuf() return true end
MemFile.__name = "FILE*"
MemFile.__tostring = function(self) return "file (virtual " .. tostring(self.name) .. ")" end

---------------------------------------------------------------- install / uninstall
local saved

local function is_read_mode(mode) return mode == nil or mode == "r" or mode == "rb" or mode == "rt" end

function V.install()
  if saved or not V.available() then return false end
  local real_open, real_lines, real_type = io.open, io.lines, io.type
  saved = { open = real_open, lines = real_lines, type = real_type }
  io.open = function(path, mode)
    if is_read_mode(mode) then
      local rel = V.normalize(path)
      if rel then return new_memfile(embedded().files[rel], rel) end
    end
    return real_open(path, mode)
  end
  io.lines = function(path, ...)
    if path ~= nil then
      local rel = V.normalize(path)
      if rel then
        local mf = new_memfile(embedded().files[rel], rel)
        return mf:lines(...)
      end
    end
    return real_lines(path, ...)
  end
  io.type = function(x)
    if getmetatable(x) == MemFile then return x.closed and "closed file" or "file" end
    return real_type(x)
  end
  return true
end

function V.uninstall()
  if not saved then return end
  io.open, io.lines, io.type = saved.open, saved.lines, saved.type
  saved = nil
end

-- run fn(...) with the virtual layer installed (restored even on error)
function V.with(fn, ...)
  local installed = V.install()
  local res = table.pack(pcall(fn, ...))
  if installed then V.uninstall() end
  if not res[1] then error(res[2], 0) end
  return table.unpack(res, 2, res.n)
end

return V
]==],
["reports/00_audit.md"] = [==[
# Phase A — Source audit and baseline (honest record)

Status vocabulary used throughout this repo (never interchangeable):
**Implemented** = executable code exists. **Verified** = named tests passed. **Measured improvement** = compared with a
legitimate baseline. **Unproven** = no sufficient evidence.

## A.1 What I could and could not read

| Item | Finding |
|---|---|
| `exec_eval_1(2).lua` (≈49,623 lines, `asi.*` modules) | **NOT AVAILABLE in this container.** The message referenced `C:\Users\Gabri\Downloads\…`, a path on your machine. `/mnt/user-data/uploads`, `/mnt/attach`, the repo (`git ls-remote` empty, 0 objects) and a filesystem-wide search for `asi.reason.hpr` all came back empty. |
| Consequence | I did **not** read `asi.util / asi.vm / asi.gl / asi.reason.* / asi.cyber.* / asi.sketch.* / asi.cli`. I cannot report their real interfaces, hashes, tests or invariants. Nothing below claims otherwise. |
| Lua runtime | Lua 5.4.6 installed via apt (`lua5.4`). |

## A.2 The seven boundary questions

Answers that come from the *directive's own description* are marked **(stated, unverified)**. Nothing was invented.

1. *Natural-language input path already exists?* **Unknown from source.** Directive states CYB1 is numeric/structured and Gen-3 uses a 4-field state: **(stated, unverified)** that there is no NL ingress.
2. *LM connected anywhere?* **Unknown from source.** No LM API, tokenizer, vector DB or memory service is assumed or invented. The pipeline is LM-independent by construction.
3. *External app supplies text?* **Unknown.** The engine therefore exposes `interpret(text, opts)` and a CLI; it does not read from any assumed channel.
4. *Reusable modules?* Cannot be decided without the source. Principles from `asi.reason.hpr` (competing hypotheses, prospective evaluation) are *re-implemented* with a language-appropriate representation instead of reusing a 4-field state.
5. *New modules required?* Everything in `asi.nlu.*` (lexing, lexicon, phrase/entity, semantics, memory, retrieval, verification, record, package, eval).
6. *Where does text preprocessing live?* **Decision: outside VM-1, as application-ingress logic**, with its own deterministic integer work meter (`asi.nlu.util.Meter`). Rationale: it is not part of any evaluated guest's reasoning, and nothing here changes VM instruction semantics, cyber scoring or frozen benchmark behaviour. No unmetered reasoning is inserted into benchmark execution because the pipeline is never invoked from the benchmark path.
7. *Accounting / memory / replay / isolation guarantees?* Cannot be confirmed against VM-1. The NLU layer provides its own: deterministic output (no clock, no randomness at runtime), integer work meter with hard budget → explicit `limited` status, namespace-isolated memory, replayable traces (`interpret-replay`).

## A.3 Baseline

- **No natural-language interpreter is known to exist in the supplied project** (cannot verify; directive implies none).
  Therefore **no numeric "existing" baseline exists** and none is invented.
- The only baseline in this repo is `asi.nlu.eval.baseline` — a *documented naive keyword/topic router I wrote*
  (first lexicon trigger wins, no sense disambiguation, no negation scope, no coreference, no relation direction).
  Any "×-reduction" is relative to that strawman and is labelled as such in `reports/`.

## A.4 Critical invariants I will not touch (cannot verify, so the integration is additive only)

- Injection is **additive**: `tools/inject_bundle.lua` inserts one `do … end` block of `package.preload["asi.nlu.*"]`
  registrations; all original bytes after the block are byte-identical (hash verified by the tool).
- If the bundle self-verifies a whole-file or per-module hash, that hash must be regenerated by the bundle's own
  generator — **I cannot do this without seeing it**. The injector prints the before/after SHA-256 so this is auditable.
- Regression of VM / cyber / reasoning / sketch behaviour is **Unproven** until you run your own test command on the
  injected file; `tools/inject_bundle.lua --selfcheck` only proves the injected file still parses (`load`) and that the
  original remainder is unchanged.

## A.5 Addendum at the end of the work (what changed since the audit)

* The host file is **still not available**; everything in A.1 and A.4 stands. Nothing in this repository was run against the real VM / cyber / reasoning / sketch code.
* The baseline in A.3 is still only my naive router; its numbers are in `reports/FINAL_REPORT.md` (blind3 0.094 vs 0.612, frozen test 0.200 vs 0.964).
* The interpretation path has no network, process, clock or randomness use and no language-model dependency (checked by search; see the final report).
* Final numbers, failure report and the list of unproven claims: `reports/FINAL_REPORT.md`; every first run of an independent set: `reports/heldout_log.md` and `reports/runs/`.
]==],
["reports/FINAL_REPORT.md"] = [==[
# Final report — asi-nlu, an LM-independent interpretation engine

Engine commit frozen for all numbers below: `e0a0bde` (branch `claude/clever-dijkstra-jdauf0`). One-file distribution: `dist/asi_nlu.lua`.
Status words (never interchangeable): **Implemented** = code exists and runs · **Verified** = an automated test passes · **Measured improvement** = a number
against a stated baseline on a stated data set with a confidence interval · **Unproven** = not demonstrated.

**No language model, no embedding, no network, no external API, no clock and no randomness is used by the interpretation path.** Checked by search:
the engine (`nlu/`) contains no socket / HTTP / `io.popen` / `os.execute` in `interpret`; `os.clock` appears only in the evaluation timers and the self-test; nothing
mentions an LLM provider or an API key.

## 1. The honest headline

| question | answer |
|---|---|
| Does it work? | Yes, on what it covers: **18/18 self-test checks from an empty directory, 121/121 unit tests, 38/38 mandatory regression cases A–J**, bit-for-bit deterministic records. |
| How well does it read **fresh wording written by someone else**? | **About 60 %.** First run of three independently authored 170-case sets: 58.2 % → 64.1 % → **61.2 %** (95 % CI ≈ ±7 points). The naive keyword baseline gets 9.4 % on the last one. |
| Is "NO MORE SEMANTIC MISROUTING" achieved? | **No.** It is not general language understanding. Where it does not understand it usually says so (low confidence, unresolved parts, abstention), but 38 % of independent cases still contain a *serious* error (wrong relation / direction / intent). See §5. |
| What is the strongest evidence? | Failures are *detectable*: the calibrated confidence ranks right above wrong with AUROC 0.85 on the independent set, and the retrieval layer gave a wrong answer in at most 1.7 % of questions on fresh phrasings while a keyword retriever was contaminated in 100 %. |

## 2. Implemented (what exists)

| phase | modules (`nlu/asi/nlu/`) |
|---|---|
| A audit / baseline | `reports/00_audit.md`; naive baseline in `eval.lua`/`baseline.lua` (a strawman I wrote, documented as such) |
| B lexical front end | `util` (meter, JSON, SHA-256), `unicode`, `lex` (strict UTF-8, numbers, dates, hostile input), `morph`, `spell` (symmetric-delete typo candidates, orthotactic non-word test), `temporal` |
| C/D semantics | `lexicon` + `data/lex_*.lua` (DSL: relations, senses, cues, entities), `lattice` (alternative segmentations, name guesses), `parse` (NP / VP / wh, normalisers), `constraints` (negation / preference / restriction scope), `frames`, `frames2`, `frames3`, `frames4` (construction hypotheses), `hyp` (type fit, binding, named-factor scoring, ambiguity), `sem` (analysis + render), `repair` |
| E memory / coreference | `memory` (layered, supersession, revocation, namespaces, structural-link selection), `coref` (pronouns, back-references, ordinals, speaker facts), `interp` (orchestration) |
| F/G data and evidence | `dataset` (JSONL / CSV / TSV / text parsed as data, never executed), `index`, `assertions`, `assertions2`, `knowledge`, `verify`, `plan`, `record` (versioned Interpretation Record + LM Input Package), `calibration`, `perturb` |
| H evaluation / delivery | `eval`, `rbench`, `longctx`, `bundler`, `package`, `injector`, `vfs`, `cli`, `main`, `engine`, `hook`; `tools/*.lua` |

Commands: `interpret`, `interpret-eval`, `interpret-report`, `interpret-trace`, `interpret-memory`, `interpret-replay` (plus `selftest`, `verify`, `bundle`, `extract` in the single file).
Controlled non-destructive injection into a host file (`tools/inject_bundle.lua`) with BEGIN/END markers, backup, idempotence and a reversible removal proven by SHA-256.

New in this last round (all with tests / dev cases): gibberish veto (orthotactics, not a word list), spoken fillers, typed bindings kept across roles,
standing-slot inheritance for bare corrections ("Sorry, I meant 2023."), comma-separated comparison lists, ellipsis after comparisons and "And of X?",
locative pro-form "there", speaker facts ("I work at X" → "my employer"), recall of earlier statements by shared content words, seeking wrappers
("Find me …", "I'm looking for …"), **numeric restrictions** ("more than 500 employees", "between 100 and 200"), wh-questions over filtered sets,
superlative questions, passive yes/no questions with and without dates, "does X have more N than Y".

## 3. Verified (automated, `lua5.4 tests/run_all.lua` and `lua5.4 dist/asi_nlu.lua selftest`)

* 121 unit tests in 11 suites (acceptance 13, dataset 12, injection 5, lex 26, memory 17, regression A–J 2, robustness 6, single-file 10, temporal 15, unicode 7, util 8) — all pass.
* Self-test of the single file from an empty directory with `package.path = ""`: **18 checks, 0 failed** (determinism across independent engines, injector round-trip, library region runs alone with no global).
* Regression examples A–J (`data/eval/regression_AJ.cases`, 38 cases): 100 %.
* Safety properties with tests: no answer without selected evidence; injected / contaminated text never promoted to a verified answer or an instruction (0/24 leaks); revoked, superseded and cross-namespace memory excluded with the exclusion recorded; budget exhaustion reported as `limited`; every hostile input yields a valid record.

## 4. Measured (all numbers re-runnable; raw outputs in `reports/runs/`)

### 4.1 Independent first runs (honest generalisation) — each set run once, before any tuning on it

| set | author | engine | n | all-fields accuracy | serious-error rate | naive baseline |
|---|---|---|---|---|---|---|
| blind1 | independent agent | e700f7d | 170 | 0.582 [0.507, 0.654] | 0.400 | — |
| blind2 | independent agent | 4c2704b | 170 | 0.641 [0.567, 0.709] | 0.347 | — |
| **blind3** | independent agent | **e0a0bde** | 170 | **0.612 [0.537, 0.682]** (0.611 [0.535, 0.681] without the 3 cases seen in the contamination notice) | 0.382 | **0.094 [0.059, 0.147]** (serious 0.876) |

Ablations on blind3 (same inputs): no hypothesis competition 0.447 · no memory 0.518 · no coreference 0.547 · no type constraints 0.594 · no suffix readings 0.594 ·
lexical-only 0.094. (Typo repair does not change gold-case accuracy but is worth +15.6 points on noisy input, below.) `reports/runs/ablations_run1.txt`.

### 4.2 Author-written sets (optimistic by construction — the engine was developed around this kind of sentence)

| set | n | accuracy |
|---|---|---|
| frozen `test` split (frozen by SHA-256 before the engine saw it; run once) | 140 | **0.964 [0.919, 0.985]**, baseline 0.200 |
| dev / val (tuned on) | 135 / 100 | 1.000 / 1.000 |
| dev constructions 1 / 2 / 3 (tuned on) | 113 / 34 / 34 | 0.982 / 1.000 / 1.000 |
| blind1 / blind2 **after** tuning (burned: development numbers, not held-out) | 170 / 170 | 0.894 / 0.988 |

Noise robustness on the test split (typo, filler, lower-case, dropped punctuation / determiner; 1541 perturbed inputs): **0.931** with repair, 0.775 without, 0.253 for the baseline.

### 4.3 Retrieval / evidence (fresh phrasings of facts and questions, held-out vocabulary)

| templates (first run) | fact-sentence coverage | question coverage | correct | wrong answer | abstained | serious error | keyword baseline serious error |
|---|---|---|---|---|---|---|---|
| heldout4 (e700f7d) | 0.342 | 0.608 | 0.192 | 0.008 | 0.800 | 0.006 | 1.000 |
| heldout5 (4c2704b) | 0.187 | 0.680 | 0.167 | 0.008 | 0.825 | 0.006 | 1.000 |
| **heldout6 (e0a0bde)** | **0.353** | **0.773** | **0.242** | **0.017** | 0.742 | **0.013 [0.003, 0.045]** | 1.000 |

So on unseen wordings the system answers about a quarter of the questions, abstains on most of the rest, and is rarely wrong; free-text *fact extraction* (a third of fresh fact sentences) is the weakest link.
On the development templates it answers 100 % correctly (0 wrong); `v_no_typed` collapses to 86 % serious error; the other retrieval ablations show no effect on this benchmark.

### 4.4 Long conversations (needed information at the beginning / middle / end of N distractor turns)

First runs on never-seen wordings: 24.6 % (heldout2) → 54.8 % (heldout3) → **75.4 % [0.672, 0.821]** (heldout4, 10 and 100 turns), memory recall 0.98, false-memory per request 1.64.
Built-in development sweep (10 / 100 / 500 turns, 189 scenarios): 100 %, false memory 0.00 (tuned on).

### 4.5 Confidence

Calibrated with a sign-constrained ridge logistic over interpretation features, cross-fitted dev↔val (never the test split): ECE 0.058, AUROC 0.825 (raw score ECE 0.172, AUROC 0.595).
Under distribution shift (`tools/calibration_shift.lua`): blind3 **ECE 0.074, AUROC 0.846** (raw 0.197 / 0.617); test ECE 0.072. The low-confidence bins really are the wrong readings
(0–27 % correct); the top bins are over-confident (stated 0.97, observed 0.80–0.93 on blind3). The record labels the calibration "valid for noisy variants of the dev/val distribution only".

### 4.6 Performance (`reports/performance.md`, deterministic work counter plus wall time on one machine)

Work per sentence is constant (230 units) from 1 to 384 sentences; the final request after 1000 turns costs the same work as after 10 (246); question work is flat in dataset size (≈ 220 units, 7–17 ms);
ingestion is linear (80 s for 19 233 records, ≈ 4 ms/record).

## 5. Failure report (blind3 first run — 66 of 170 cases; classification is mine)

| root cause | cases (examples) | n |
|---|---|---|
| **Carrier phrases hide the question**: the request sits after a long lead-in or before a trailing remark; the clause-suffix mechanism does not fire because a "good-looking" empty statement reading blocks it | E002 "…needs to know the currency of Norway", E005, E008, E012, E040, E041, E043, E050, E149, E156, E157, E162 | 12 |
| **Missing lexicalisations of relation words / idioms** | E014 "came up with" (inventor), E025 "put money into" (investor), E028 "who all works for", E087 "make up", E159 "big cheese", E115/E116/E158 "have Portuguese as an official language / whose official language is French", E007, E045 "besides", E080, E161 | 13 |
| **Standing style / format instructions** are not turned into persistent preferences ("Always give me distances in kilometres", "Keep it under 100 words", "From now on call me …") | E090–E096, E099 | 9 |
| Comparison / choice forms | E069, E071, E075, E109, E131 | 5 |
| Multi-turn references | E134 "which country did I ask about first", E137 "the first company", E139 "the other one", E140, E141 | 5 |
| Negation / complement over typed sets | E035, E036, E038, E049 | 4 |
| Typos inside names and relation words | E143, E145, E146, E147 | 4 |
| "which N [in P] verb object" filters | E082, E088, E117 | 3 |
| Temporal forms ("as of", "used to be", "will host", "founded after") | E052, E057, E058 | 3 |
| Multi-word names with `&` / "to the" / lower-case input | E009, E015, E077, E078, E081 | 5 |
| Intent labels (translate, causes), ambiguity flag | E105, E110, E068 | 3 |

What this says: the architecture (competing hypotheses, typed roles, explicit memory) holds; the *coverage of surface constructions* is the limit. Each class above is a bounded
piece of work (cues, lexicalisations, a suffix trigger that ignores empty statement readings, a persistent-preference frame); none needs a model. I did not tune on blind3 after seeing its failures.

## 6. Unproven / not done

* **Host regression is Unproven.** `exec_eval_1(2).lua` (≈ 49 k lines: VM, cyber, reasoning, sketch) was never available in the container. Injection was proven non-destructive on synthetic hosts only; run your own test command on an injected copy (`tools/inject_bundle.lua --target HOST.lua --selfcheck`, which writes `HOST.asi.lua` and leaves `HOST.lua` untouched).
* **General language understanding** is not shown — see §1 and §5. English only; no multilingual claim.
* "Independent" sets were written by sub-agents of the same model family, not by people; independence is limited.
* Retrieval ablations other than `typed` and `reliability` show no effect here (redundant mechanisms or an insensitive benchmark) — their individual contributions are unproven.
* Long-context results at 500 turns exist only for the built-in (tuned) wordings; blind wordings were run at 10 and 100 turns.
* Wall-clock figures come from one machine; only the work counter is machine-independent.

## 7. Protocol notes

* Gold edits after seeing engine output are logged in `reports/gold_changes.md` (D093, V066: `neg=none` removed). Harness changes: `dep=earlier_context` accepted as an alias of `earlier_project_context`; new `pos=numeric:` key; fuzzy-resolved mentions judged by entity name; parent-relation acceptance in the long-context scorer.
* `reports/heldout_log.md` records every first run and one contamination notice: three blind3 gold lines (E129, E133, E140) were displayed before its first run; the engine was not edited for them and blind3 is reported with and without them.
* The frozen test split's SHA-256 is verified by `lua5.4 tools/manifest.lua check`.

## 8. Using the single file

```
lua5.4 asi_nlu.lua selftest                                   # 18 checks, from any directory
lua5.4 asi_nlu.lua interpret "Which cities in Germany have more than a million inhabitants?" --json
lua5.4 asi_nlu.lua interpret-trace "Who put money into Quenby Robotics?"
lua5.4 asi_nlu.lua interpret-eval --split test                # the gold sets are embedded
lua5.4 asi_nlu.lua tool run_eval --file some.cases            # every evaluation tool is embedded (run_eval, run_noise, run_longctx, run_perf, ...)
lua5.4 asi_nlu.lua report FINAL_REPORT                        # this report
lua5.4 asi_nlu.lua bundle --out asi_nlu_bundle.lua            # the package.preload library text (host injection)
lua5.4 asi_nlu.lua inject --target HOST.lua --selfcheck       # writes HOST.asi.lua, leaves HOST.lua untouched
lua5.4 asi_nlu.lua extract DIR                                # write every embedded source / data / test / report file into DIR
lua5.4 asi_nlu.lua verify                                     # SHA-256 integrity of every embedded file
```
]==],
["reports/calibration.md"] = [==[
# Confidence calibration (interpretation correctness)

Target: P(all gold fields of a case are satisfied) given the raw `semantic_raw` score (posterior of the winning hypothesis).
Data: gold cases of the dev and val splits (single-turn, 6 perturbed variants per case plus the original; deterministic seed 11).
Perturbations (see `asi.nlu.perturb`): typos in non-entity words, filler words, lower-casing, dropped punctuation, dropped determiners.
The frozen test split is NOT used. Dev gold was used to tune the interpreter, so dev/original accuracy is optimistic by construction; the perturbed
variants are what give the calibration data its errors. The calibration is valid only for this distribution of inputs.

